# The shared part of the benchmark runners: what differs between BlitzLLVM and the original Blitz3D, building and running a
# benchmark program, reading its RESULT line, and printing and saving the result. A runner (dungeon.py, flythrough.py, ...) only
# adds its own options and lines; the Blitz side has the same split (bench_begin.bi, bench_end.bi, bench_llvm.bi, bench_original.bi,
# see README.adoc).
#
# Every benchmark program is built under a random file name. Windows (Auto HDR, the game detection of Game Bar) and graphics drivers
# (NVIDIA and AMD application profiles) pick settings by the name of the executable, and a known name such as dungeon.exe can get a
# frame rate cap or a different present path that has nothing to do with the program: on Areldir (180 Hz VRR HDR display) Windows
# and the NVIDIA driver treat dungeon.exe as a game, and it was held to the refresh rate while it had focus, with BlitzLLVM and the
# original Blitz3D alike.
import argparse
import csv
import datetime
import json
import os
import platform
import re
import secrets
import shutil
import sys
import tempfile
import time
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../tools"))
import procutil  # noqa: E402

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)

# Direct3D 7 limits the window to 2048 in each direction (measured on Areldir: 2048x2048 works, 2049x1080 and 500x3000 fail): the
# original Blitz3D then stops with "Unable to create 3D Scene".
ORIGINAL_MAX_SIZE = 2048

# The include files of the Blitz side that every benchmark gets next to its source: the shared start and end, and the file of the
# compiler (bench_llvm.bi or bench_original.bi), copied as bench_compiler.bi.
SHARED_INCLUDES = ("bench_begin.bi", "bench_end.bi")


def program_name():
    """A file name, without extension, that no program, game or driver profile has: a letter and 12 random hex digits."""
    return "b" + secrets.token_hex(6)


def program_path(directory, exe=None):
    """Where to build a benchmark program in directory, under a random name (.exe on Windows, or when exe is true). $BENCH_PROGRAM (a
    full path) is one fixed path for every program instead, for a machine where the GPU of a program is set per path in Windows
    (Settings, Graphics: a laptop that has to run the original Blitz3D on its dedicated GPU). The file there is removed first, so a
    build that fails can't leave the program of the one before."""
    fixed = os.environ.get("BENCH_PROGRAM")
    if fixed:
        os.makedirs(os.path.dirname(os.path.abspath(fixed)), exist_ok=True)
        if os.path.isfile(fixed):
            os.remove(fixed)
        return os.path.abspath(fixed)
    if exe is None:
        exe = platform.system() == "Windows"
    return os.path.join(directory, program_name() + (".exe" if exe else ""))


def find_compiler(given):
    if given:
        return given
    for candidate in (os.path.join(ROOT, "build", "code_compiler", "blitzcc"), os.path.join(ROOT, "build", "code_compiler", "blitzcc.exe"),
                      os.path.join(ROOT, "build", "distrib", "bin", "blitzcc.exe")):
        if os.path.isfile(candidate):
            return candidate
    return shutil.which("blitzcc") or sys.exit("blitzcc not found, build it or pass --blitzcc.")


def copy_synced(source, target):
    """Copies a file without a UTF-8 byte order mark (the original compiler stops at it with "Expecting end-of-file", and Windows tools
    like to add one) and makes sure it is on disk and can be read again before the compiler looks for it."""
    with open(source, "rb") as f:
        data = f.read()
    if data.startswith(b"\xef\xbb\xbf"):
        data = data[3:]
    with open(target, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    for attempt in range(20):
        try:
            with open(target, "rb") as f:
                if f.read() == data:
                    return
        except OSError:
            pass
        time.sleep(0.25)
    sys.exit("Could not read back %s." % target)


def copy_includes(directory, name, llvm, profile=False):
    """Copies the Blitz include files of benchmark name next to its source in directory: the shared ones, the one of the compiler as
    bench_compiler.bi, the benchmark's own part for the compiler (<name>_llvm.bi or <name>_original.bi) as <name>_compiler.bi, and
    bench_profile_on.bi (a BlitzLLVM build with --profile) or bench_profile_off.bi as bench_profile.bi."""
    variant = "llvm" if llvm else "original"
    copy_synced(os.path.join(HERE, "bench_profile_%s.bi" % ("on" if llvm and profile else "off")), os.path.join(directory, "bench_profile.bi"))
    for f in SHARED_INCLUDES:
        copy_synced(os.path.join(HERE, f), os.path.join(directory, f))
    copy_synced(os.path.join(HERE, "bench_%s.bi" % variant), os.path.join(directory, "bench_compiler.bi"))
    own = os.path.join(HERE, "%s_%s.bi" % (name, variant))
    if os.path.isfile(own):
        copy_synced(own, os.path.join(directory, name + "_compiler.bi"))


def parse_gpu(output):
    """The GPU time of the passes from the once-a-second report of BLITZLLVM_PROFILE_FPS=1 (summed over the frames of that second; the
    first second, making the scene, is left out, the others are averaged per frame). Empty without such lines. The benchmarks read
    ProfileValue after every frame instead (bench_profile_on.bi); this is for history.py and builds from before ProfileValue."""
    frames_shown = 0
    sums = {"scene": 0.0, "2d": 0.0, "copy": 0.0, "present": 0.0, "frame": 0.0}
    shown = None
    first = True
    for line in output.splitlines():
        m = re.match(r"fps: (\d+),", line)
        if m:
            shown = int(m.group(1))
            continue
        m = re.match(r"\s+gpu passes: scene ([\d.]+) ms, 2d ([\d.]+) ms, copy ([\d.]+) ms, present ([\d.]+) ms, frame ([\d.]+) ms", line)
        if m and shown:
            if first:
                first = False
                continue
            frames_shown += shown
            for k, v in zip(sums, m.groups()):
                sums[k] += float(v)
    if not frames_shown:
        return {}
    gpu = {"gpu_" + k + "_ms": v / frames_shown for k, v in sums.items()}
    gpu["gpu_frames"] = frames_shown
    return gpu


class Runner:
    """Runs benchmarks/<name>.bb. The options every benchmark has are made here; a runner adds its own to .parser before parse()."""

    def __init__(self, name, doc, frames=300, quick_frames=30, warmup=5, size="640x360", own=None):
        """own is the name of the benchmark's own include files (<own>_llvm.bi, <own>_original.bi), when it shares them with another
        benchmark (loading_meshes uses the ones of loading)."""
        self.name = name
        self.own = own or name
        self.parser = argparse.ArgumentParser(description=doc.split("\n\n")[0], formatter_class=argparse.RawDescriptionHelpFormatter, epilog=doc)
        p = self.parser
        p.add_argument("--blitzcc", help="the compiler: BlitzLLVM's blitzcc or the original Blitz3D's bin/blitzcc.exe")
        p.add_argument("--frames", type=int, default=int(os.environ.get("BENCH_FRAMES", frames)), help="frames that are timed (default %(default)s)")
        p.add_argument("--warmup", type=int, default=int(os.environ.get("BENCH_WARMUP", warmup)), help="frames before them that are not timed (default %(default)s)")
        p.add_argument("--seed", type=int, default=int(os.environ.get("BENCH_SEED", 1)))
        p.add_argument("--size", default=os.environ.get("BENCH_SIZE", size), help="size of the window, WxH (default %(default)s)")
        p.add_argument("--depth", type=int, default=int(os.environ.get("BENCH_DEPTH", 0)), help="graphics depth for Graphics3D (0, the default, is what the program picks)")
        p.add_argument("--gpu", type=int, default=int(os.environ.get("BENCH_GPU", 0)), help="graphics driver for SetGfxDriver (0, the default, is what the program picks)")
        p.add_argument("--quick", action="store_true", help="a small run (%d frames) for a look whether it works" % quick_frames)
        p.add_argument("--debug", action="store_true", help="build with -d (no optimization)")
        p.add_argument("--profile", action="store_true", help="build with --profile and read the GPU time of the passes with ProfileValue every frame; BlitzLLVM only")
        p.add_argument("--label", default="", help="name of this run in the result, such as the GPU")
        p.add_argument("--shot", help="save the last frame to this file")
        p.add_argument("--no-save", action="store_true", help="don't write benchmarks/results/")
        self.quick_frames = quick_frames
        self.args = None
        self.values = {}
        self.gpu = {}
        self.frametimes = []
        self.output = ""

    def parse(self):
        """Reads the options, finds the compiler and checks what every benchmark checks. Returns the options."""
        args = self.args = self.parser.parse_args()
        if args.quick:
            args.frames = self.quick_frames
        self.width, self.height = (int(v) for v in args.size.lower().split("x"))
        self.compiler = find_compiler(args.blitzcc)
        # The original Blitz3D prints only a version number for -v and has no optimization level or profiling, BlitzLLVM prints
        # "Compiler version:...". The same program is built with either, so that their speeds can be compared.
        version = " ".join(procutil.run([self.compiler, "-v"], capture_output=True, text=True).stdout.split())
        self.llvm = bool(re.search(r"Compiler version:20\d\d\.", version))
        if not self.llvm:
            # The original compiler reads its runtime and libraries from BLITZPATH, the folder that has bin\ in it; without it, it
            # prints an error instead of its version.
            os.environ.setdefault("BLITZPATH", os.path.dirname(os.path.dirname(os.path.abspath(self.compiler))))
            version = " ".join(procutil.run([self.compiler, "-v"], capture_output=True, text=True).stdout.split())
        self.version = version
        self.flags = ["-d"] if args.debug else (["-O3"] if self.llvm else [])
        if args.profile and self.llvm:
            self.flags.append("--profile")
        self.original_limit(self.width > ORIGINAL_MAX_SIZE or self.height > ORIGINAL_MAX_SIZE,
                            "The original Blitz3D (Direct3D 7) cannot open a window above %dx%d, it stops with \"Unable to create 3D Scene\" (asked for %dx%d); "
                            "use --size %dx%d or less with it, or BlitzLLVM for larger windows." % (ORIGINAL_MAX_SIZE, ORIGINAL_MAX_SIZE, self.width, self.height, ORIGINAL_MAX_SIZE, ORIGINAL_MAX_SIZE))
        # Without a display the program runs under xvfb-run, which with Mesa means llvmpipe.
        self.display = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") or platform.system() == "Windows" else \
            ["xvfb-run", "-a", "-s", "-screen 0 %dx%dx24" % (self.width, self.height)]
        if self.display and not shutil.which("xvfb-run"):
            sys.exit("There is no display and no xvfb-run.")
        return args

    def original_limit(self, exceeded, message):
        """Stops with message when the original Blitz3D is the compiler and a limit of it is exceeded."""
        if exceeded and not self.llvm:
            sys.exit(message)

    def run(self, env, what, files=()):
        """Builds and runs the benchmark with env (its own BENCH_ variables) added to the common ones; what says what runs. files are
        more files to copy next to the source. Returns the values of the RESULT line, and keeps the GPU times and the frame times."""
        with tempfile.TemporaryDirectory() as directory:
            program = self.build(directory, files)
            print("Running %s, %d frames, %dx%d, build %s" % (what, self.args.frames, self.width, self.height, " ".join(self.flags) or "no options"), flush=True)
            return self.execute(program, directory, env)

    def build(self, directory, files=()):
        """Builds the benchmark in directory under a random name and returns the path of the program. files are more files to copy
        next to the source."""
        program = program_path(directory)
        # Compiled from a copy with the includes of this compiler next to it, whatever folder the original compiler resolves
        # includes from.
        source = os.path.join(directory, self.name + ".bb")
        copy_synced(os.path.join(HERE, self.name + ".bb"), source)
        copy_includes(directory, self.own, self.llvm, self.args.profile)
        for f in files:
            shutil.copy(f, directory)
        # A build that fails with an include error (a file that is not visible yet right after it was written, seen with the
        # original on Windows) is tried again a few times.
        for attempt in range(5):
            build = procutil.run([self.compiler, "-q"] + self.flags + ["-o", program, source], cwd=directory, capture_output=True, text=True)
            if build.returncode == 0 or "include" not in (build.stdout + build.stderr).lower():
                break
            time.sleep(1 + attempt)
        if build.returncode != 0:
            sys.exit("Building the benchmark failed (exit code %d):\n%s" % (build.returncode, (build.stdout + build.stderr)[-2000:]))
        return program

    def execute(self, program, directory, env):
        """Runs program (from build) in directory with env (its own BENCH_ variables) added to the common ones. Returns the values of
        the RESULT line, and keeps the GPU times and the frame times."""
        args = self.args
        full = dict(os.environ, BENCH_FRAMES=str(args.frames), BENCH_WARMUP=str(args.warmup), BENCH_SEED=str(args.seed), BENCH_W=str(self.width),
                    BENCH_H=str(self.height), BENCH_DEPTH=str(args.depth), BENCH_GPU=str(args.gpu),
                    BENCH_FRAMETIMES=os.path.join(directory, "frametimes.txt"), BENCH_RESULT=os.path.join(directory, "result.txt"))
        full.update({k: str(v) for k, v in env.items()})
        if args.shot:
            full["BENCH_SHOT"] = os.path.abspath(args.shot)
        for f in (full["BENCH_RESULT"], full["BENCH_FRAMETIMES"]):
            if os.path.isfile(f):
                os.remove(f)
        result = procutil.run(self.display + [program], env=full, capture_output=True, text=True, cwd=directory)
        self.output = result.stdout + result.stderr
        # The original Blitz3D has no stdout for a program, so the result is read from a file.
        line = None
        if os.path.isfile(full["BENCH_RESULT"]):
            line = next((l for l in open(full["BENCH_RESULT"]).read().splitlines() if "RESULT " in l or l.startswith("ERROR")), None)
        if line is not None and line.startswith("ERROR"):
            sys.exit("The benchmark stopped: %s" % line)
        if result.returncode != 0 or line is None:
            sys.exit("The benchmark failed (exit code %d):\n%s" % (result.returncode, self.output[-2000:]))
        self.values = {k: float(v) for k, v in re.findall(r"(\w+)=([-+\d.eE]+)", line.split("RESULT ", 1)[1])}
        self.gpu = {k: v for k, v in self.values.items() if k.startswith("gpu_") or k == "renderworld_ms"}
        self.frametimes = []
        if os.path.isfile(full["BENCH_FRAMETIMES"]):
            self.frametimes = [int(float(l)) for l in open(full["BENCH_FRAMETIMES"]).read().split()]
        return self.values

    def record(self):
        return {
            "date": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds"),
            "label": self.args.label,
            "compiler": self.version if self.llvm else "Blitz3D " + self.version,
            "build": " ".join(self.flags),
            "platform": platform.platform(),
            "display": "xvfb" if self.display else "native",
            "result": self.values,
            "gpu": self.gpu,
        }

    def report(self, lines=(), update=None):
        """Prints lines (the benchmark's own, before the common ones) and the frame times and counts. update, when given, says what the
        timed update of a frame does (it is part of ms/frame)."""
        v = self.values
        print()
        for line in lines:
            print("  " + line)
        print("  created in  %12.0f ms" % v.get("create_ms", 0))
        if update:
            print("  update      %12.2f ms/frame (%s, part of ms/frame)" % (v.get("update_ms", 0), update))
        print("  ms/frame    avg %.2f  min %.2f  median %.2f  p95 %.2f  max %.2f" % (v["ms_avg"], v["ms_min"], v["ms_median"], v["ms_p95"], v["ms_max"]))
        print("  fps         %12.1f" % v["fps"])
        print("  per frame   %.0f triangles, %.0f draw calls, %.0f pipeline binds, %.0f texture binds, %.0f buffer binds"
              % (v["tris"], v["draws"], v["pipelines"], v["textures"], v["buffers"]))
        if self.gpu:
            if "gpu_frames" in self.gpu:
                print("  gpu         scene %.3f ms, 2d %.3f ms, copy %.3f ms, present %.3f ms, frame %.3f ms per frame (%d of %d frames, ProfileValue)"
                      % (self.gpu["gpu_scene_ms"], self.gpu["gpu_2d_ms"], self.gpu["gpu_copy_ms"], self.gpu["gpu_present_ms"], self.gpu["gpu_frame_ms"], self.gpu["gpu_frames"],
                         self.values["frames"]))
                if "gpu_lag" in self.gpu:
                    print("  gpu lag     the first GPU time came back at the Flip of frame %d (the warmup frames counted)" % self.gpu["gpu_lag"])
            else:
                print("  gpu         no GPU time came back (no GPU timestamps on this device?)")
            print("  cpu         RenderWorld %.3f ms, waiting for the GPU %.3f ms per frame (ProfileValue)" % (self.gpu.get("renderworld_ms", 0), self.gpu.get("gpu_wait_ms", 0)))
        print("  window      %.0fx%.0f, depth %.0f" % (v.get("width", 0), v.get("height", 0), v.get("depth", 0)))
        print("  build       %s (%s)" % (" ".join(self.flags) or "no options", self.version or "unknown compiler"))

    def save(self, tag, fields):
        """Saves the result as benchmarks/results/<name>-<date>-<tag>.json and adds it to <name>.csv, with the RESULT values fields
        (the benchmark's own) and the common ones."""
        if self.args.no_save:
            return
        common = ("frames", "seed", "width", "height", "depth", "update_ms", "ms_avg", "ms_min", "ms_median", "ms_p95", "ms_max", "fps",
                  "tris", "draws", "pipelines", "textures", "buffers")
        out = os.path.join(HERE, "results")
        os.makedirs(out, exist_ok=True)
        record = self.record()
        stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        name = "%s-%s-%s" % (self.name, stamp, tag)
        with open(os.path.join(out, name + ".json"), "w") as f:
            json.dump(dict(record, frame_times_us=self.frametimes), f, indent=1)
        csv_path = os.path.join(out, self.name + ".csv")
        columns = list(fields) + [c for c in common if c not in fields]
        header = ["date", "label", "build", "display"] + columns + ["gpu_scene_ms", "gpu_frame_ms"]
        if os.path.isfile(csv_path):
            with open(csv_path, newline="") as f:
                if next(csv.reader(f), None) != header:
                    # Written by an older runner with other columns: kept under another name, so that no row ends up under the wrong column.
                    os.replace(csv_path, os.path.join(out, "%s-%s-old.csv" % (self.name, stamp)))
        new = not os.path.isfile(csv_path)
        with open(csv_path, "a", newline="") as f:
            writer = csv.writer(f)
            if new:
                writer.writerow(header)
            writer.writerow([record["date"], self.args.label, record["build"], record["display"]] + [self.values.get(k, "") for k in columns]
                            + [self.gpu.get("gpu_scene_ms", ""), self.gpu.get("gpu_frame_ms", "")])
        print("  saved       benchmarks/results/%s.json and %s.csv" % (name, self.name))
